INSERT INTO field_definition(id,code,label_vi,section_code,data_type,canonical_unit,scope_status,storage_level,min_value,max_value,validation_rule,help_text,source_ref) VALUES ('2ca11529-be49-5d2d-8738-8bd323322aab','bat_thuong_cau_truc_tim','Bất thường cấu trúc/chức năng tim đã được xác nhận','can_lam_sang','boolean',NULL,'mvp','workflow_value',NULL,NULL,'{"workflowSchema": {"oneOf": [{"type": "object", "properties": {"value_state": {"const": "answered"}, "value": {}, "unit": {"type": ["string", "null"]}, "measuredAt": {"anyOf": [{"type": "string", "format": "date-time"}, {"type": "null"}]}}, "required": ["value_state", "value"], "additionalProperties": false}, {"type": "object", "properties": {"value_state": {"const": "unknown"}, "value": {"type": "null"}, "unit": {"type": ["string", "null"]}, "measuredAt": {"anyOf": [{"type": "string", "format": "date-time"}, {"type": "null"}]}, "reason": {"type": "string", "minLength": 1}}, "required": ["value_state", "value"], "additionalProperties": false}]}, "workflowContract": "hf-workflow/1.0", "step": null, "unknownClearsValue": true}','thang thử nghiệm, chờ bác sĩ duyệt','C1-contract.md §3; G1-review.md §6') ON CONFLICT(code) DO NOTHING;
