INSERT INTO field_ai_module(field_definition_id,ai_module_code,is_required,source_stt_refs) VALUES('2ca11529-be49-5d2d-8738-8bd323322aab','ai_lab_test',true,'C1 test workflow') ON CONFLICT DO NOTHING;
DO $$ DECLARE base form_version%ROWTYPE; target uuid; admin_id uuid; s record; f record; ord integer; BEGIN
      PERFORM pg_advisory_xact_lock(hashtext('hf-workflow-form-v12'));
      IF EXISTS(SELECT 1 FROM form_version WHERE version_label='v1.2') THEN RETURN; END IF;
      SELECT * INTO STRICT base FROM form_version WHERE version_label='v1.1' ORDER BY version_no DESC LIMIT 1;
      SELECT id INTO STRICT admin_id FROM app_user WHERE username='admin_demo';
      target := gen_random_uuid();
      INSERT INTO form_version(id,form_template_id,version_no,version_label,based_on_version_id,change_note,created_by,definition_overrides)
      VALUES(target,base.form_template_id,3,'v1.2',base.id,'C3: workflow synthetic, thang thử nghiệm, chờ bác sĩ duyệt',admin_id,
        base.definition_overrides || '{"_workflow":{"contractVersion":"hf-workflow/1.0","mappingVersion":"hf-map/1.1-test"}}'::jsonb);
      FOR s IN SELECT * FROM form_section WHERE form_version_id=base.id ORDER BY display_order LOOP
        INSERT INTO form_section(form_version_id,section_code,title_vi,description,display_order)
        VALUES(target,s.section_code,s.title_vi,s.description,s.display_order);
        ord:=0;
        FOR f IN SELECT ff.*,fd.code FROM form_field ff JOIN field_definition fd ON fd.id=ff.field_definition_id
           WHERE ff.form_section_id=s.id ORDER BY ff.display_order LOOP
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm,is_visible,is_readonly,custom_label_vi,custom_help_text)
          SELECT target,id,f.field_definition_id,ord,f.required_for_confirm,f.is_visible,f.is_readonly,f.custom_label_vi,f.custom_help_text
          FROM form_section WHERE form_version_id=target AND section_code=s.section_code;
IF s.section_code='trieu_chung_dien_bien' AND f.code='kho_tho_khi_gang_suc' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='kho_tho_nang';
          END IF;
IF s.section_code='trieu_chung_dien_bien' AND f.code='phu_hai_chi_duoi' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='phu_chi_duoi_muc_do';
          END IF;
IF s.section_code='trieu_chung_dien_bien' AND f.code='thay_doi_can_nang_kg' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='bien_thien_can_nang_7ngay';
          END IF;
IF s.section_code='trieu_chung_dien_bien' AND f.code='lu_lan_sang' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='trieu_chung_khong_dien_hinh';
          END IF;
IF s.section_code='lao_khoa' AND f.code='lao_khoa_frailty' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='danh_gia_suy_yeu_frailty';
          END IF;
IF s.section_code='can_lam_sang' AND f.code='cls_sieu_am_tim_ket_luan' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='e_over_a_ratio';
          END IF;
IF s.section_code='can_lam_sang' AND f.code='cls_egfr' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='egfr_ckd_epi';
          END IF;
IF s.section_code='can_lam_sang' AND f.code='cls_egfr' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='egfr_formula';
          END IF;
IF s.section_code='can_lam_sang' AND f.code='cls_ecg_ket_luan' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='ecg_12_chuyen_dao';
          END IF;
IF s.section_code='can_lam_sang' AND f.code='cls_xquang_ket_luan' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='xquang_nguc_thang';
          END IF;
IF s.section_code='can_lam_sang' AND f.code='cls_sieu_am_tim_ket_luan' THEN
          ord:=ord+1;
          INSERT INTO form_field(form_version_id,form_section_id,field_definition_id,display_order,required_for_confirm)
          SELECT target,fs.id,fd.id,ord,false FROM form_section fs CROSS JOIN field_definition fd
          WHERE fs.form_version_id=target AND fs.section_code=s.section_code AND fd.code='bat_thuong_cau_truc_tim';
          END IF;
END LOOP; END LOOP; END $$;
COMMIT;
